import { useState } from "react";
import { Mail, Phone, MapPin, Send, User, MessageSquare, Clock, CheckCircle } from "lucide-react";

export default function Contact() {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    subject: "",
    message: "",
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitStatus, setSubmitStatus] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      await new Promise(resolve => setTimeout(resolve, 1500));

      setSubmitStatus({
        type: 'success',
        message: 'Message envoyé avec succès ! Nous vous répondrons dans les plus brefs délais.'
      });

      // Réinitialisation du formulaire
      setFormData({ name: "", email: "", phone: "", subject: "", message: "" });

      // Suppression du message de succès après 5 secondes
      setTimeout(() => setSubmitStatus(null), 5000);
    } catch (error) {
      setSubmitStatus({
        type: 'error',
        message: 'Une erreur est survenue. Veuillez réessayer ou nous contacter directement.'
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const contactInfo = [
    {
      icon: Mail,
      title: "Email",
      content: "contact@entreprise.com",
      subContent: "support@entreprise.com",
      color: "from-blue-500 to-cyan-500",
      gradient: "bg-gradient-to-br",
      action: "mailto:contact@entreprise.com"
    },
    {
      icon: Phone,
      title: "Téléphone",
      content: "+33 1 23 45 67 89",
      subContent: "+33 6 12 34 56 78",
      color: "from-emerald-500 to-green-500",
      gradient: "bg-gradient-to-br",
      action: "tel:+33123456789"
    },
    {
      icon: MapPin,
      title: "Bureaux",
      content: "123 Avenue des Champs-Élysées",
      subContent: "75008 Paris, France",
      color: "from-purple-500 to-pink-500",
      gradient: "bg-gradient-to-br",
      action: "https://maps.google.com/?q=Paris,France"
    },
    {
      icon: Clock,
      title: "Horaires",
      content: "Lun - Ven: 9h - 18h",
      subContent: "Samedi: 10h - 14h",
      color: "from-amber-500 to-orange-500",
      gradient: "bg-gradient-to-br",
      action: null
    }
  ];

  const subjects = [
    "Demande générale",
    "Support technique",
    "Devis / Proposition",
    "Partenariat",
    "Autre"
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 via-white to-indigo-50 py-16 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto">
        {/* En-tête */}
        <div className="text-center mb-16">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-gradient-to-br from-indigo-500 to-blue-600 rounded-2xl shadow-lg mb-6">
            <MessageSquare className="w-10 h-10 text-white" />
          </div>
          <h1 className="text-4xl md:text-5xl lg:text-6xl font-bold text-gray-900 mb-4">
            Contactez-<span className="bg-gradient-to-r from-indigo-600 to-blue-600 bg-clip-text text-transparent">nous</span>
          </h1>
          <p className="text-gray-600 text-lg md:text-xl max-w-3xl mx-auto leading-relaxed">
            Notre équipe est à votre écoute pour répondre à toutes vos questions et accompagner vos projets
          </p>
        </div>

        {/* Grille principale */}
        <div className="grid lg:grid-cols-3 gap-8 lg:gap-12">
          {/* Informations de contact */}
          <div className="lg:col-span-1">
            <div className="sticky top-8">
              <div className="bg-gradient-to-br from-white to-gray-50 rounded-3xl shadow-xl p-8 border border-gray-100">
                <h2 className="text-2xl font-bold text-gray-900 mb-8 flex items-center gap-3">
                  <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-blue-500 rounded-lg flex items-center justify-center">
                    <User className="w-5 h-5 text-white" />
                  </div>
                  Nos coordonnées
                </h2>

                <div className="space-y-6">
                  {contactInfo.map((item, idx) => (
                    <a
                      key={idx}
                      href={item.action}
                      target={item.action?.startsWith('http') ? "_blank" : "_self"}
                      rel="noopener noreferrer"
                      className={`block group ${item.action ? 'cursor-pointer hover:scale-[1.02]' : 'cursor-default'}`}
                    >
                      <div className="flex items-start gap-4 p-4 rounded-2xl transition-all duration-300 group-hover:bg-gray-50">
                        <div className={`flex-shrink-0 w-12 h-12 ${item.gradient} ${item.color} rounded-xl flex items-center justify-center shadow-md`}>
                          <item.icon className="w-6 h-6 text-white" />
                        </div>
                        <div className="flex-1">
                          <h3 className="font-semibold text-gray-900">{item.title}</h3>
                          <p className="text-gray-700 mt-1">{item.content}</p>
                          {item.subContent && (
                            <p className="text-gray-500 text-sm mt-1">{item.subContent}</p>
                          )}
                        </div>
                      </div>
                    </a>
                  ))}
                </div>

                {/* Statistiques */}
                <div className="mt-10 pt-8 border-t border-gray-200">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="text-center p-4 bg-blue-50 rounded-2xl">
                      <div className="text-2xl font-bold text-blue-600">24/7</div>
                      <div className="text-sm text-gray-600 mt-1">Support</div>
                    </div>
                    <div className="text-center p-4 bg-green-50 rounded-2xl">
                      <div className="text-2xl font-bold text-green-600">1h</div>
                      <div className="text-sm text-gray-600 mt-1">Réponse moyenne</div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Formulaire */}
          <div className="lg:col-span-2">
            <div className="bg-white rounded-3xl shadow-xl p-8 md:p-10 border border-gray-100">
              <div className="mb-10">
                <h2 className="text-3xl font-bold text-gray-900 mb-3">
                  Envoyez-nous un message
                </h2>
                <p className="text-gray-600">
                  Remplissez le formulaire ci-dessous et nous vous répondrons dans les plus brefs délais
                </p>
              </div>

              {/* Message de statut */}
              {submitStatus && (
                <div className={`mb-8 p-4 rounded-2xl ${
                  submitStatus.type === 'success' 
                    ? 'bg-green-50 border border-green-200' 
                    : 'bg-red-50 border border-red-200'
                }`}>
                  <div className="flex items-center gap-3">
                    {submitStatus.type === 'success' ? (
                      <CheckCircle className="w-5 h-5 text-green-600" />
                    ) : (
                      <div className="w-5 h-5 rounded-full bg-red-600 flex items-center justify-center">
                        <span className="text-white text-xs">!</span>
                      </div>
                    )}
                    <p className={submitStatus.type === 'success' ? 'text-green-700' : 'text-red-700'}>
                      {submitStatus.message}
                    </p>
                  </div>
                </div>
              )}

              <form onSubmit={handleSubmit} className="space-y-8">
                <div className="grid md:grid-cols-2 gap-8">
                  <div>
                    <label className="block text-gray-700 font-medium mb-2">
                      Nom complet *
                    </label>
                    <input
                      type="text"
                      name="name"
                      value={formData.name}
                      onChange={handleChange}
                      placeholder="Votre nom et prénom"
                      className="w-full px-5 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all duration-300"
                      required
                    />
                  </div>

                  <div>
                    <label className="block text-gray-700 font-medium mb-2">
                      Email *
                    </label>
                    <input
                      type="email"
                      name="email"
                      value={formData.email}
                      onChange={handleChange}
                      placeholder="email@exemple.com"
                      className="w-full px-5 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all duration-300"
                      required
                    />
                  </div>

                  <div>
                    <label className="block text-gray-700 font-medium mb-2">
                      Téléphone
                    </label>
                    <input
                      type="tel"
                      name="phone"
                      value={formData.phone}
                      onChange={handleChange}
                      placeholder="+33 1 23 45 67 89"
                      className="w-full px-5 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all duration-300"
                    />
                  </div>

                  <div>
                    <label className="block text-gray-700 font-medium mb-2">
                      Sujet *
                    </label>
                    <select
                      name="subject"
                      value={formData.subject}
                      onChange={handleChange}
                      className="w-full px-5 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all duration-300"
                      required
                    >
                      <option value="">Sélectionnez un sujet</option>
                      {subjects.map((subject, idx) => (
                        <option key={idx} value={subject}>{subject}</option>
                      ))}
                    </select>
                  </div>
                </div>

                <div>
                  <label className="block text-gray-700 font-medium mb-2">
                    Message *
                  </label>
                  <textarea
                    name="message"
                    value={formData.message}
                    onChange={handleChange}
                    rows="6"
                    placeholder="Décrivez votre projet ou votre question en détail..."
                    className="w-full px-5 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all duration-300 resize-none"
                    required
                  />
                </div>

                <div className="pt-4">
                  <button
                    type="submit"
                    disabled={isSubmitting}
                    className={`w-full md:w-auto min-w-[200px] px-8 py-4 bg-gradient-to-r from-indigo-600 to-blue-600 text-white font-semibold rounded-xl shadow-lg hover:shadow-xl transition-all duration-300 transform hover:-translate-y-0.5 flex items-center justify-center gap-3 ${
                      isSubmitting ? 'opacity-75 cursor-not-allowed' : ''
                    }`}
                  >
                    {isSubmitting ? (
                      <>
                        <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                        Envoi en cours...
                      </>
                    ) : (
                      <>
                        Envoyer le message
                        <Send className="w-5 h-5" />
                      </>
                    )}
                  </button>

                  <p className="text-gray-500 text-sm mt-4">
                    * Champs obligatoires. Vos données sont traitées confidentiellement.
                  </p>
                </div>
              </form>
            </div>

            {/* Section supplémentaire */}
            <div className="mt-8 grid md:grid-cols-3 gap-6">
              <div className="bg-gradient-to-br from-blue-50 to-indigo-50 p-6 rounded-2xl border border-blue-100">
                <h3 className="font-semibold text-gray-900 mb-2">Réponse rapide</h3>
                <p className="text-gray-600 text-sm">Nous nous engageons à répondre sous 1 heure ouvrée</p>
              </div>
              <div className="bg-gradient-to-br from-emerald-50 to-green-50 p-6 rounded-2xl border border-emerald-100">
                <h3 className="font-semibold text-gray-900 mb-2">Support expert</h3>
                <p className="text-gray-600 text-sm">Notre équipe spécialisée vous accompagne</p>
              </div>
              <div className="bg-gradient-to-br from-purple-50 to-pink-50 p-6 rounded-2xl border border-purple-100">
                <h3 className="font-semibold text-gray-900 mb-2">Confidentialité</h3>
                <p className="text-gray-600 text-sm">Vos données sont sécurisées et protégées</p>
              </div>
            </div>
          </div>
        </div>

        <div className="mt-16 text-center">
          <div className="inline-flex items-center gap-2 bg-gradient-to-r from-indigo-500 to-blue-500 text-white px-6 py-3 rounded-full shadow-lg">
            <Clock className="w-5 h-5" />
            <span className="font-semibold">Disponible du lundi au vendredi, 9h-18h</span>
          </div>
          <p className="text-gray-600 mt-6">
            Vous pouvez aussi nous joindre directement par téléphone au{" "}
            <a href="tel:+33123456789" className="text-blue-600 font-semibold hover:underline">
              +33 1 23 45 67 89
            </a>
          </p>
        </div>
      </div>
    </div>
  );
}
